"use client";

import { useState } from "react";
import { CheckCircle2, AlertCircle, Calendar } from "lucide-react";
import { verifySurveilansBatch } from "@/services/ppi";
import { useRouter } from "next/navigation";

export default function TabelVerifikasi({ data = [] }: { data: any[] }) {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const router = useRouter();

  // 1. Fungsi Pilih Semua
  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      const allIds = data.map((item) => item.id);
      setSelectedIds(allIds);
    } else {
      setSelectedIds([]);
    }
  };

  // 2. Fungsi Pilih Per Baris
  const handleSelectOne = (id: string) => {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((i) => i !== id) : [...prev, id]
    );
  };

  // 3. Fungsi Eksekusi Verifikasi (Server Action)
  const handleVerify = async () => {
    if (selectedIds.length === 0) return;
    
    const confirmVerif = confirm(`Verifikasi ${selectedIds.length} data sekarang?`);
    if (!confirmVerif) return;

    setIsProcessing(true);
    try {
      const res = await verifySurveilansBatch(selectedIds);
      if (res.success) {
        setSelectedIds([]); // Reset pilihan
        router.refresh();   // Update data di layar secara instan
        alert("Data berhasil diverifikasi!");
      } else {
        alert("Gagal memverifikasi data.");
      }
    } catch (error) {
      console.error(error);
      alert("Terjadi kesalahan sistem.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
      {/* Header Tabel dengan Tombol Aksi */}
      <div className="p-8 border-b border-slate-50 flex flex-col md:flex-row justify-between items-center gap-4">
        <div>
          <h2 className="text-xl font-bold text-slate-800">Antrean Verifikasi</h2>
          <p className="text-sm text-slate-500 font-medium font-sans">
            Pilih laporan perawat untuk divalidasi
          </p>
        </div>
        <button
          onClick={handleVerify}
          disabled={selectedIds.length === 0 || isProcessing}
          className="w-full md:w-auto flex items-center justify-center gap-2 bg-emerald-600 text-white px-8 py-3.5 rounded-2xl text-xs font-bold hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-100 disabled:bg-slate-200 disabled:shadow-none active:scale-95"
        >
          <CheckCircle2 size={18} />
          {isProcessing ? "Menyimpan..." : `Verifikasi ${selectedIds.length} Laporan`}
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50/50">
              <th className="p-6 w-10 text-center">
                <input
                  type="checkbox"
                  onChange={handleSelectAll}
                  checked={data.length > 0 && selectedIds.length === data.length}
                  className="w-4 h-4 rounded border-slate-300 text-blue-600 accent-blue-600 cursor-pointer"
                />
              </th>
              <th className="p-6 text-[10px] font-black text-slate-400 uppercase tracking-widest font-sans">Info Pasien</th>
              <th className="p-6 text-[10px] font-black text-slate-400 uppercase tracking-widest font-sans">Unit / Ruangan</th>
              <th className="p-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center font-sans">Tindakan</th>
              <th className="p-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center font-sans">HAIs</th>
              <th className="p-6 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center font-sans">Status</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50 font-sans">
            {data.length === 0 ? (
              <tr>
                <td colSpan={6} className="p-12 text-center text-slate-400 font-medium italic">
                  Tidak ada data yang menunggu verifikasi.
                </td>
              </tr>
            ) : (
              data.map((row) => {
                const hasHais = Number(row.vap) > 0 || Number(row.hap) > 0 || Number(row.isk) > 0 || Number(row.iad) > 0;
                return (
                  <tr key={row.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="p-6 text-center">
                      <input
                        type="checkbox"
                        checked={selectedIds.includes(row.id)}
                        onChange={() => handleSelectOne(row.id)}
                        className="w-4 h-4 rounded border-slate-300 text-blue-600 accent-blue-600 cursor-pointer"
                      />
                    </td>
                    <td className="p-6">
                      <div className="flex flex-col">
                        <span className="text-sm font-bold text-slate-700 uppercase tracking-tight">{row.nama_pasien || row.no_rm}</span>
                        <span className="text-[10px] text-slate-400 flex items-center gap-1 mt-1 font-bold">
                          <Calendar size={10} /> {new Date(row.tanggal).toLocaleDateString('id-ID')}
                        </span>
                      </div>
                    </td>
                    <td className="p-6">
                      <span className="text-xs font-bold text-slate-600 uppercase tracking-wide">
                        {row.master_ruangan?.nama_ruangan || "Tanpa Unit"}
                      </span>
                    </td>
                    <td className="p-6 text-center">
                      <span className="text-xs font-extrabold text-slate-500">
                        {Number(row.uc || 0) + Number(row.cvl || 0) + Number(row.ivl || 0) + Number(row.ett || 0)} <small className="opacity-50">Hari</small>
                      </span>
                    </td>
                    <td className="p-6 text-center">
                      {hasHais ? (
                        <span className="px-3 py-1 bg-red-50 text-red-600 rounded-lg text-[9px] font-black uppercase tracking-tighter">Ada Temuan</span>
                      ) : (
                        <span className="text-slate-300 text-[9px] font-bold uppercase">Nihil</span>
                      )}
                    </td>
                    <td className="p-6 text-center">
                      <div className="flex items-center justify-center gap-1 text-slate-400 font-black text-[10px] uppercase italic">
                        <AlertCircle size={14} className="text-amber-500" /> Pending
                      </div>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}